def preserve_legacy_academic_values(apps, schema_editor):
    Enrollment = apps.get_model('academics', 'Enrollment')
    for row in Enrollment.objects.all().iterator():
        row.status = 'active' if row.active else 'withdrawn'
        row.save(update_fields=['status'])

    Assignment = apps.get_model('academics', 'TeachingAssignment')
    for assignment in Assignment.objects.select_related('class_group').all().iterator():
        assignment.subject_id = assignment.class_group.legacy_subject_id
        assignment.save(update_fields=['subject'])

    Assessment = apps.get_model('academics', 'Assessment')
    for assessment in Assessment.objects.select_related('legacy_class_group').all().iterator():
        candidates = Assignment.objects.filter(class_group_id=assessment.legacy_class_group_id)
        if candidates.count() == 1:
            assessment.assignment_id = candidates.first().pk
            assessment.save(update_fields=['assignment'])

    Attendance = apps.get_model('academics', 'Attendance')
    for row in Attendance.objects.all().iterator():
        row.status = 'present' if row.present else 'absent'
        row.save(update_fields=['status'])

    Notification = apps.get_model('academics', 'Notification')
    for row in Notification.objects.filter(title='').iterator():
        row.title = row.category[:160]
        row.save(update_fields=['title'])


